INSERT INTO camps (name, operator_name, website_url, registration_url, email, phone, street_address, city, state, zip, region, camp_type, primary_categories, secondary_categories, activities, gender_policy, age_min, age_max, grade_min, grade_max, description_short, indoor_outdoor, religious_affiliation, price_min, price_max, price_per_week, price_per, extended_care, transportation, meals_included, financial_aid, refund_policy_summary, special_needs_notes, swim_waterfront_notes, aca_accredited, aca_source_url, season_year, id, slug, location, is_day_camp, is_sleepaway, is_specialty, stem_focus, arts_focus, sports_focus, nature_focus, verification_status, sources, last_reviewed_date, last_updated_date, is_active) VALUES
('LetGoYourMind – Bedford, NH (One Church - Bedford Outpost)', 'LetGoYourMind', 'https://www.letgoyourmind.com/location/nh/bedford', 'https://www.ultracamp.com/clientlogin.aspx?idCamp=290&campcode=lym&lang=en-Us&return=registration/selectattendees.aspx?idsession=433465', 'Admin@LetGoYourMind.com', NULL, NULL, 'Bedford', 'NH', '03110', 'New Hampshire', 'specialty', ARRAY['STEM','technology']::text[], NULL, ARRAY['Motorized LEGO building','Drag-and-drop coding of LEGO builds','LEGO MINDSTORMS EV3 robotics','LEGO stop-motion animation and film editing','Minecraft command generators','LEGO mini-challenges']::text[], NULL, 4, 13, NULL, NULL, 'A weekly LEGO STEM day program at One Church - Bedford Outpost. Ages 4-5 come for a morning of simple motorized LEGO builds (9am-12pm), and ages 6-13 come 9am-3pm for LEGO building, coding or EV3 robotics, stop-motion animation and, for ages 9-13, Minecraft commands.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, 'Cancel in writing (email is fine) by April 30; no cancellations are accepted after May 1. A cancellation gets a credit toward next summer, less a $99 non-refundable fee. Cancellations 14 days before the session get a credit of 50% of tuition.', NULL, NULL, NULL, NULL, 2027, 'aa528440-e0b5-5960-8d43-9716bee137c3', 'letgoyourmind-bedford-nh-one-church-bedford-outpost-bedford', ST_GeogFromText('SRID=4326;POINT(-71.5369 42.9356)'), FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://tools.usps.com/zip-code-lookup.htm?citybyzipcode','https://www.letgoyourmind.com/faq','https://www.letgoyourmind.com/location/nh/bedford']::text[], '2026-11-13', '2026-11-13', TRUE),
('Melody Pines Day Camp', NULL, 'https://melodypines.com/', 'https://melodypines.campbrainregistration.com/', NULL, '(603) 669-9414', '510 Corning Road', 'Manchester', 'NH', '03109', 'New Hampshire', 'day', NULL, NULL, ARRAY['Swimming lessons','Boating (canoes, rowboats, kayaks)','Stand-up paddleboarding','Water-skiing','Arts and crafts','Skits','Soccer','Hockey','Basketball','Volleyball','Lacrosse','Pickleball','Archery','BB-gun shooting','Rock wall climbing','Gaga','Pond life']::text[], NULL, 5, NULL, 0, 8, 'Private day camp in Manchester, NH for children entering grades K–8, with separate girls'' and boys'' groups by grade. Tuition covers a full day from 7:30am to 5:00pm and includes swimming lessons; only full weeks can be booked.', NULL, NULL, 425, 425, 425, 'week', NULL, NULL, NULL, FALSE, 'You must pay a non-refundable, non-transferable deposit for each week at registration. If you cancel before May 1, you get a refund minus the deposit. After May 1, you owe for all reserved weeks. The remaining balance is due by May 15; if it isn''t paid by then, your weeks are cancelled and you lose the deposit. Credit card payments carry a 3% surcharge, and returned checks cost $30.', NULL, 'Three swimming areas bounded by docks and ropes, each with a raft for advanced swimmers. Over 30 Red Cross certified lifeguards. Every camper takes a swim check on day one and a mandatory daily lesson by level; those who pass the Rafter''s Test can take out their own boats and learn to water-ski. Motorboat drivers are licensed by NH Marine Patrol.', NULL, NULL, 2027, '230fb4bf-0e30-590d-aa32-8a8ae15037c1', 'melody-pines-day-camp-manchester', ST_GeogFromText('SRID=4326;POINT(-71.4548 42.9956)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://melodypines.com/registration/','https://melodypines.com/the-camp-day/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Stewards Summer Camp', 'Seacoast Science Center', 'https://www.seacoastsciencecenter.org/camps/stewards-summer-camp/', NULL, 'h.burke@sscnh.org', '603-436-8043', '570 Ocean Boulevard', 'Rye', 'NH', '03870', 'New Hampshire', 'day', ARRAY['nature','STEM']::text[], NULL, ARRAY['Tide pooling','Field trips','Kayaking','Seine netting','Community science','Whale watching','Sailing','Hiking','Canoeing','Surfing','Stand-up paddle boarding','Snorkeling','Beach clean-ups','Low ropes course']::text[], NULL, NULL, NULL, 6, 8, 'An outdoor day program for grades 6-8 where campers learn about coastal ecosystems and how people affect them. Each week has a theme, with field trips, tide pooling, kayaking and beach stewardship around the NH, ME and MA coast.', NULL, NULL, 475, 525, 525, 'week', FALSE, TRUE, FALSE, TRUE, 'Cancel more than two weeks before your child''s first day of camp and you get a 50% refund. After that, no refunds.', NULL, 'The program includes kayaking (Session C, with Monday-Tuesday for beginners and Wednesday-Friday for experienced paddlers), surfing, stand-up paddle boarding and snorkeling (Session E), and boat trips. The camp provides all equipment. A kayak waiver is required. Swim test requirements are not stated.', NULL, NULL, 2026, '8306187e-f361-50b5-b551-a744e0d44c2c', 'stewards-summer-camp-rye', ST_GeogFromText('SRID=4326;POINT(-70.7192 43.0335)'), TRUE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.seacoastsciencecenter.org/camps/stewards-summer-camp/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Wildwood Camp', 'Mass Audubon', 'https://www.massaudubon.org/programs-events/nature-camps/wildwood-camp/programs', 'https://www.massaudubon.org/programs?prg%5Bpid%5D%5B%5D=17542&prg%5Bdaterange%5D=&prg%5Bquery%5D=&prg%5Bprogram_types%5D%5B%5D=849&prg%5Binclude_camps%5D=1&prg%5Bsubmit%5D=&prg%5Bage_min%5D=&prg%5Bage_max%5D=', NULL, '603-899-5589', '27 Vining Road', 'Rindge', 'NH', '03461', 'New Hampshire', 'sleepaway', ARRAY['nature']::text[], NULL, ARRAY['Swimming and paddling on Hubbard Pond','Campfires and s''mores','Overnight camping trips','Tent setup and knot tying','High and low ropes courses','Archery','Hiking','Climbing','Kayaking','Backpacking','Themed camp days','Leadership training']::text[], NULL, 9, 17, NULL, NULL, 'Mass Audubon''s overnight nature camp on Hubbard Pond in Rindge, NH, for ages 9-17. Campers 9-14 come for one- or two-week sessions; teens choose weekly adventure trips, Counselors-in-Training or Environmental Leadership Teens. All sessions require a Mass Audubon Family membership.', NULL, NULL, 625, 3415, 1860, 'week', NULL, NULL, NULL, TRUE, NULL, NULL, 'The camp''s waterfront is on Hubbard Pond, where campers swim and paddle. The pages don''t describe swim tests or waterfront staffing.', NULL, NULL, 2027, 'ad9906ec-e17d-53f1-8d7a-e127616f9b1b', 'wildwood-camp-rindge', ST_GeogFromText('SRID=4326;POINT(-72.0132 42.7567)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.massaudubon.org/programs-events/nature-camps/wildwood-camp','https://www.massaudubon.org/programs-events/nature-camps/wildwood-camp/programs','https://www.massaudubon.org/programs-events/nature-camps/wildwood-camp/rates-dates']::text[], '2026-11-13', '2026-11-13', TRUE),
('YMCA Camp Coniston', 'YMCA Camp Coniston', 'https://coniston.org/dates-and-fees/', 'https://coniston.campintouch.com/ui/forms/application/camper/App', 'office@coniston.org', '603-863-1160', '24 Coniston Road', 'Grantham', 'NH', '03753', 'New Hampshire', 'sleepaway', ARRAY['general','outdoor']::text[], NULL, ARRAY['Swimming lessons','Canoeing','Kayaking','Sailing (Sunfish)','Stand-up paddleboarding','Snorkeling','Archery','Riflery','Horseback riding (extra fee)','Ropes course and climbing tower','CampCraft','Arts and crafts','Drama','Dance','Music','Basketball','Lacrosse','Soccer','Tennis','Adventure trips','Habitat for Humanity service trips','Red Cross Lifeguard Training (CIT)']::text[], NULL, 8, 16, NULL, NULL, 'YMCA overnight camp in New Hampshire offering one- and two-week overnight sessions for ages 8–15, plus 6-day Adventure Camp trips for ages 12–15. It also runs Habitat for Humanity service trips and a 4-week CIT program for older teens.', NULL, NULL, 1100, 6850, NULL, NULL, NULL, NULL, TRUE, TRUE, NULL, NULL, 'Camp is on Lake Coniston. Every camper takes swimming lessons in groups by swim level; snorkeling requires passing the swim test. Campers also canoe, kayak, paddleboard and sail Sunfish on the lake.', NULL, NULL, 2027, '33e10bc8-dba4-5f79-b873-5aaa6a141dfe', 'ymca-camp-coniston-grantham', ST_GeogFromText('SRID=4326;POINT(-72.1491 43.5166)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://coniston.org/dates-and-fees/','https://coniston.org/over-night-camp/','https://coniston.org/program-areas/']::text[], '2026-11-13', '2026-11-13', TRUE),
('YMCA Day Camp of Hooksett', 'The Granite YMCA', 'https://www.graniteymca.org/camps/day-camp/hooksett/', 'https://ymcagranite.sgasoftware.com/Sales/Product?ProductID=62001-68999&ProductTypeID=610,650&DT=GroupedList&DL=100', 'kprovost@graniteymca.org', '603.623.3558', NULL, 'Hooksett', 'NH', '03106', 'New Hampshire', 'day', ARRAY['sports','arts','nature']::text[], NULL, ARRAY['swimming','sports','adventure','archery','arts & crafts','gaga ball','nature','weekly theme weeks','teen weekly trips','community service','leadership training']::text[], NULL, 6, 16, 1, 11, 'A YMCA day camp at Hooksett Memorial School for ages 6–16, with weekly themes. Activities include swimming (at the YMCA of Downtown Manchester), sports, archery, arts & crafts, gaga ball and nature. There are also teen camp, Leader In Training and Counselor In Training programs.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, TRUE, 'A $35 deposit per week is non-refundable. Cancel more than 6 weeks before the camp week for a full refund less the deposit; 3 to 6 weeks before, a $65 admin fee also applies; less than 3 weeks before, no refund.', NULL, 'Swimming happens off-site at the YMCA of Downtown Manchester. The page does not describe swim levels or supervision.', NULL, NULL, 2026, 'bb80c1b1-f2ca-5af4-b744-ad6c770ae13c', 'ymca-day-camp-of-hooksett-hooksett', ST_GeogFromText('SRID=4326;POINT(-71.4466 43.0812)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://tools.usps.com/zip-code-lookup.htm?citybyzipcode','https://www.graniteymca.org/camps/day-camp/hooksett/','https://www.graniteymca.org/dev/wp-content/uploads/2024/01/Summer-Billing-Schedule.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('Kabeyun', 'The John & Anna Newton Porter Foundation', 'https://kabeyun.org/', 'https://kabeyun.campintouch.com/ui/forms/application/camper/App', NULL, '603-875-3060', '43 Camp Kabeyun Rd', 'Alton Bay', 'NH', '03810', 'New Hampshire', 'sleepaway', NULL, NULL, ARRAY['Individual challenge sports','Creative arts','Adventure trips','Sailing','Tennis','Pottery','Archery','Fishing','Waterskiing']::text[], 'boys', 8, 17, NULL, NULL, 'Overnight summer camp for boys ages 8 to 16 in Alton Bay, New Hampshire. Most campers attend one of two half-summer sessions. There is also a full-summer option, shorter introductory sessions for first-time campers ages 8 to 11, and a counseling internship for returning campers ages 16 and 17.', NULL, NULL, 5550, 12840, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2027, 'bfde4fd2-0fb0-50fb-847f-6286a78feefb', 'kabeyun-alton-bay', ST_GeogFromText('SRID=4326;POINT(-71.2406 43.4883)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://kabeyun.org/about-camp/activities/','https://kabeyun.org/for-parents/sessions-tuition-and-dates/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Little Investigators Summer Program (Nashua YMCA Day Camps)', 'YMCA of Greater Nashua', 'https://nmymca.org/camps/nashua-day-camps/', 'https://nmymca.org/programregistration', 'camp@nmymca.org', '603-598-1533', '24 Stadium Drive', 'Nashua', 'NH', '03062', 'New Hampshire', 'day', ARRAY['nature','STEM']::text[], NULL, ARRAY['Swimming','Nature exploration','Science experiments','Storytelling','Water play','Building with child-safe tools','Cooking/snack making','Gardening','Arts and crafts','Role-play']::text[], NULL, 3, 5, NULL, NULL, 'A half-day preschool summer camp for ages 3-5 at the Nashua YMCA. It runs Monday to Friday, 9 AM to 1 PM, with a new theme each week, such as nature, water play, science and dinosaurs, and swim time once a week.', NULL, NULL, 180, 195, 180, 'week', FALSE, NULL, NULL, TRUE, NULL, 'Children must be potty trained to attend.', 'Children swim once per week in the Nashua Y pool. Week 2 includes water play such as sprinklers and bubbles.', NULL, NULL, 2026, '8281f6ba-7de7-5ab6-992a-af00e310e91b', 'little-investigators-summer-program-nashua-ymca-day-camps-nashua', ST_GeogFromText('SRID=4326;POINT(-71.4676 42.7654)'), TRUE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://nmymca.org/camps/nashua-day-camps/','https://nmymca.org/wp-content/uploads/2026/01/YMCAofGN_SummerCampGuide_2026_Final.1.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('Meredith Parks and Recreation Summer Camp', 'Meredith Parks and Recreation Department', 'https://www.meredithnh.gov', 'https://meredithnh.recdesk.com/Community/Home', 'parksnrec@meredithnh.gov', '603-279-8197', 'One Circle Drive', 'Meredith', 'NH', '03253', 'New Hampshire', 'day', ARRAY['general']::text[], NULL, ARRAY['active and passive games','cooperative activities','arts and crafts','daily outside time','walks','baking/cooking','field trips']::text[], NULL, 5, NULL, 0, 8, 'A town-run weekday day camp at the Meredith Community Center for kids entering grades K-8. Activities include games, arts and crafts, daily outside time, walks, baking and cooking, and field trips.', NULL, NULL, 63, 175, 125, 'week', TRUE, NULL, NULL, NULL, 'Prices are weekly and there are no daily rates. You are not reimbursed for days your child is absent. If your child is signed up for a week with a field trip, you owe the field trip fee. Changing 3-day option days needs two weeks'' written notice, or you are charged the full-week price.', 'If your child gets extra help from staff at school, email Sarah (sperkins@meredithnh.gov) to set up a meeting about camp options for your child.', NULL, NULL, NULL, 2026, 'de3d56f5-d3ba-5122-9b69-75833c4be219', 'meredith-parks-and-recreation-summer-camp-meredith', ST_GeogFromText('SRID=4326;POINT(-71.4986 43.6312)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://meredithnh.gov/DocumentCenter/View/1653/Summer-Camp-2026-NOTICE---Price-Increase-PDF?bidId=','https://www.meredithnh.gov/424/Registration']::text[], '2026-11-13', '2026-11-13', TRUE),
('Opechee Day Camp', 'Laconia Parks & Recreation', 'https://www.laconianh.gov/927/Opechee-Day-Camp', NULL, NULL, '603-524-5046', NULL, 'Laconia', 'NH', '03246', 'New Hampshire', 'day', NULL, NULL, ARRAY['games','arts and crafts','beach trips']::text[], NULL, NULL, NULL, 0, 5, 'A summer day camp for children in kindergarten through grade 5, run by Laconia Parks & Recreation. Activities include games, arts and crafts, and trips to the beach.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '7f7c1ce2-588e-5e9a-a95f-9b1a7ccadd18', 'opechee-day-camp-laconia', ST_GeogFromText('SRID=4326;POINT(-71.4823 43.5765)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.laconianh.gov/927/Opechee-Day-Camp']::text[], '2026-11-13', '2026-11-13', TRUE),
('William Lawrence Camp', NULL, 'https://wlcamp.org/', 'https://wlcamp.campintouch.com/ui/forms/application/camper/App', 'knoll@wlcamp.org', '603-569-3698', '139 Federal Corner Road', 'Center Tuftonboro', 'NH', '03816', 'New Hampshire', 'sleepaway', ARRAY['nature','sports']::text[], NULL, ARRAY['Swimming','Sailing','Canoeing and kayaking','Waterskiing','Tubing','Fishing','Low and high ropes','Climbing tower','Archery','Riflery','Skeet shooting (senior campers)','Fly fishing and tying','Wilderness skills','Woodworking','Soccer','Basketball','Tennis','Volleyball']::text[], 'boys', NULL, NULL, 3, 11, 'A nonprofit overnight camp for boys entering grades 3 to 10 on 250 acres in Center Tuftonboro, in New Hampshire''s Lakes Region. Founded in 1913. Cabins have no electricity, boys spend the summer away from screens, and activities include archery, sailing, waterskiing, team sports and wilderness trips.', NULL, NULL, 1905, 7350, NULL, NULL, NULL, NULL, TRUE, TRUE, 'A $500 enrollment deposit is refundable until December 1, 2026, then nonrefundable. Tuition is nonrefundable; the camp recommends tuition refund insurance through CampMinder. Final payment is due May 15, 2027.', NULL, 'Waterfront on Lower Beech Pond. Regular swimming lessons taught by Red Cross certified instructors, plus daily free swim. Sailing, canoeing, kayaking, waterskiing, tubing and catch-and-release fishing.', NULL, NULL, 2027, '7a753470-ba0a-52a7-b186-dc780c95df7e', 'william-lawrence-camp-center-tuftonboro', ST_GeogFromText('SRID=4326;POINT(-71.2759 43.6699)'), FALSE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 'unverified', ARRAY['https://wlcamp.org/','https://wlcamp.org/about/program/','https://wlcamp.org/enrollment/dates-rates/']::text[], '2026-11-13', '2026-11-13', TRUE),
('YMCA Camp Foss', 'Granite YMCA', 'https://campfoss.org/', 'https://campfoss.org/sign-up-for-camp/', 'stownes@graniteymca.org', '603-232-8642', '242 Willey Pond Rd', 'Strafford', 'NH', '03884', 'New Hampshire', 'sleepaway', NULL, NULL, ARRAY['Campfires','Specialty activities','Socials with Camp Mi-Te-Na','Out-of-camp trips and excursions','Sign-up activities']::text[], 'girls', 7, 15, NULL, NULL, 'A YMCA overnight summer camp for girls ages 8 to 15, with 7-year-olds welcome in the fourth session. Stays run one week, two weeks, one month or the full summer, from June 27 to August 21, 2027, with Sunday check-in and Saturday check-out. Older teens can apply to the Counselor in Training program.', NULL, NULL, 1650, 10450, NULL, NULL, NULL, NULL, TRUE, TRUE, 'To cancel for a non-medical reason, you must tell the Enrollment Coordinator at least four weeks before the session starts. Deposits paid at registration are non-refundable. Medical cancellations need a doctor''s note. The final payment is due May 15, 2027. Discounts: 10% off for Granite YMCA members, 10% off per new friend referred, and 5% off per sibling.', NULL, NULL, NULL, NULL, 2027, '0d65e043-5c28-5762-b629-efe526f1f8ec', 'ymca-camp-foss', ST_GeogFromText('SRID=4326;POINT(-71.17 43.2754)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://campfoss.org/','https://campfoss.org/contact/','https://campfoss.org/dates-and-rates/','https://campfoss.org/food-and-nutrition/','https://campfoss.org/our-story/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Keene Family YMCA Summer Camps', 'Keene Family YMCA', 'https://keeneymca.org/programs-classes/summer-camps/', 'https://operations.daxko.com/Programs/Redirector.aspx?cc_category_id=2576484&cid=3011', 'memberservices@keene-ymca.org', '603.352.6002', '200 Summit Road', 'Keene', 'NH', '03431', 'New Hampshire', 'day', ARRAY['general','sports']::text[], ARRAY['arts','STEM','adventure','leadership']::text[], ARRAY['group games','STEM projects','arts and crafts','team-building','gymnastics','Ninja Room obstacle courses','swimming','water play','hiking','field trips','basketball','soccer','frisbee/ultimate/disc golf','multi-sport','STEAM','leadership training (CIT/LIT)','First Aid/CPR/AED certification']::text[], NULL, NULL, NULL, 0, 12, 'The Keene Family YMCA runs weekly summer day camps: Camp Wakonda, a general day camp with a new theme each week, plus specialty weeks for gymnastics, adventure trips, sports, art and STEAM, some of them half days. Leadership programs serve grades 6-12. In 2026 the Y said final camp locations would be shared before camp.', NULL, NULL, 100, 335, 260, 'week', TRUE, NULL, NULL, TRUE, 'A $25 per week deposit and a $20 registration fee per child are due at registration; the balance is charged 14 days before camp. Refunds, less the deposit, only for cancellations more than 30 days before camp; none for not attending, with medical exceptions considered. Changing camps or weeks costs $10 and can be done up to 14 days before camp.', 'Families of children with special needs or who need accommodations should contact the relevant Camp Director before registering.', 'Gymnastics, Obstacle and Sports camps include time in the Y pool. Adventure Camp may visit local beaches. Swim supervision and swim tests are not described.', NULL, NULL, 2026, 'd940b7f5-ad98-53d7-b8c1-834301543154', 'keene-family-ymca-summer-camps-keene', ST_GeogFromText('SRID=4326;POINT(-72.3069 42.9538)'), TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://keeneymca.org/programs-classes/summer-camps/','https://keeneymca.org/wp-content/uploads/2026/06/Camp-Guide-2026.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('Londonderry Day Camp (Camp Pa-Gon-Ki)', 'The Granite YMCA (YMCA of Greater Londonderry)', 'https://www.graniteymca.org/camps/day-camp/londonderry/', 'https://ymcagranite.sgasoftware.com/Sales/Product?DL=50&BranchID=40&ProductTypeID=650', 'jbuck@graniteymca.org', '603.437.9622', '206 Rockingham Rd', 'Londonderry', 'NH', '03053', 'New Hampshire', 'day', ARRAY['nature','sports','arts']::text[], NULL, ARRAY['Swimming','Structured games','Theme weeks','Camp songs and traditions','Cooking (specialty)','Sports (specialty)','Art (specialty)','Lego (specialty)','Pokémon (specialty)','Leadership training (LIT/CIT)']::text[], NULL, NULL, NULL, 1, 11, 'A traditional outdoor day camp run by the YMCA of Greater Londonderry for children entering grades 1-9, with weekly themes, camp songs and add-on specialty camps. Camp runs 8:30 am to 4:00 pm with free before and after care, and teens entering grades 8-11 can join Leader in Training and Counselor in Training programs.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, TRUE, 'A $35 nonrefundable deposit is due per camper per week. Cancel more than 6 weeks before a camp week for a full refund less the deposit; 3 to 6 weeks before, a $65 admin fee also applies; under 3 weeks, no refund. Balances are drafted about 6 weeks before each week.', NULL, 'Swimming is listed as an afternoon activity. The Londonderry Y campus, which hosts day camp, has an outdoor pool. Swim tests and supervision are not described.', NULL, NULL, 2026, '8f41ac52-e437-5583-863b-97d59ee05c66', 'londonderry-day-camp-camp-pa-gon-ki-londonderry', ST_GeogFromText('SRID=4326;POINT(-71.3923 42.8798)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.graniteymca.org/camps/day-camp/londonderry/','https://www.graniteymca.org/dev/wp-content/uploads/2024/01/Summer-Billing-Schedule.pdf','https://www.graniteymca.org/location/londonderry/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Metropolis of Boston Camp', 'Greek Orthodox Metropolis of Boston', 'https://www.metropolisofbostoncamp.org/', 'https://gomb.campintouch.com/ui/forms/application/camper/App', NULL, '(617) 651-1369', '329 Camp Merrimac Road', 'Contoocook', 'NH', '03229', 'New Hampshire', 'sleepaway', ARRAY['faith']::text[], NULL, ARRAY['swimming','canoeing','tubing','water trampoline','basketball','soccer','arts and crafts','hiking trails','chapel services','campfires']::text[], NULL, 8, 18, 3, 12, 'An overnight Orthodox Christian camp run by the Greek Orthodox Metropolis of Boston on over 300 acres in Contoocook, NH. Campers entering grades 3-12 come for one 6-day summer session (Monday to Sunday), living in cabins grouped by age; weekend fall and winter camps serve grades 6-12.', NULL, 'Greek Orthodox', 550, 650, 650, 'week', NULL, NULL, TRUE, TRUE, NULL, 'Nut-free facility; the kitchen can handle most nut, gluten and dairy allergies, and sets up a separate storage area for more serious allergies. Families should contact the office early about medical needs; a Camper Support page covers accommodations.', 'Campers must pass a swim test before waterfront activities. Lifeguards watch the waterfront at better than Red Cross ratios, no one swims without a lifeguard, and campers use a buddy system.', NULL, NULL, 2026, '15dfa61f-5bb7-5f16-8fdf-7c6ccd2f792e', 'metropolis-of-boston-camp-brookline', ST_GeogFromText('SRID=4326;POINT(-71.7131 43.2307)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.metropolisofbostoncamp.org/campgrounds--facilities.html','https://www.metropolisofbostoncamp.org/contact-us.html','https://www.metropolisofbostoncamp.org/dates--rates.html','https://www.metropolisofbostoncamp.org/frequently-asked-questions.html','https://www.metropolisofbostoncamp.org/summer-camp.html']::text[], '2026-11-13', '2026-11-13', TRUE),
('Pierce Camp Birchmont', NULL, 'https://www.campbirchmont.com/', 'https://www.campbirchmont.com/enroll/', 'mail@campbirchmont.com', '603-569-1337', '693 Governor John Wentworth Hwy', 'Wolfeboro', 'NH', '03894', 'New Hampshire', 'sleepaway', ARRAY['general','sports']::text[], ARRAY['arts','adventure','sailing','swimming','nature']::text[], ARRAY['archery','arts and crafts','badminton','baseball/softball','basketball','boating','challenge course','dance and yoga','fishing','flag football','swimming','ga-ga','golf','gymnastics','hockey','horseback riding','lacrosse','mountain biking','nature and orienteering','ninja warrior','overnight camping','paddle sports','performing arts','pottery','sailing','soccer','tennis','volleyball','woodworking']::text[], 'coed', 7, 15, NULL, NULL, 'A family-owned co-ed overnight camp for ages 7 to 15 on Lake Wentworth in Wolfeboro, NH, with 30-plus activities across aquatics, athletics, arts and adventure. Families choose a 7-week full season, a 4- or 3-week session, or a 2-week introductory session for first-timers or campers in grades 1-3.', NULL, NULL, 6950, 17450, NULL, 'session', NULL, TRUE, TRUE, NULL, NULL, 'Nut-safe kitchen with no nut products or oils; vegetarian options at every meal, and gluten-free and kosher-style menus can be accommodated.', 'Waterfront on Lake Wentworth (state Class A water, sandy bottom, little boat traffic) with nearly half a mile of private sandy beach. Campers can join swim meets and sailing regattas.', NULL, NULL, 2027, 'b3f538aa-1f6c-501f-949a-18a68a772cea', 'pierce-camp-birchmont-wolfeboro', ST_GeogFromText('SRID=4326;POINT(-71.1692 43.6144)'), FALSE, TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.campbirchmont.com/','https://www.campbirchmont.com/the-birchmont-experience/dates-rates-faqs/','https://www.campbirchmont.com/the-birchmont-experience/lets-eat/','https://www.campbirchmont.com/the-birchmont-experience/our-activities/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Water Monkey Camp', NULL, 'https://www.watermonkeycamp.com', 'https://www.watermonkeycamp.com/enrollment-form', 'evan@watermonkeycamp.com', '(617) 855-9253', '298 Merrymeeting Road', 'New Durham', 'NH', '03855', 'New Hampshire', 'sleepaway', ARRAY['sports']::text[], NULL, ARRAY['Wakeboarding','Waterskiing','Wakesurfing','Wake skating','Land-based activities','Multi-sport field']::text[], 'coed', 9, 17, NULL, NULL, 'Overnight watersports camp on Merrymeeting Lake in New Durham, NH, focused on wakeboarding, waterskiing, wakesurfing and wake skating. Each Sunday-to-Friday week takes at most 9 boys and girls ages 9-17, who live in lakeside cabins with their counselors.', NULL, NULL, 3500, 3500, 3500, 'week', NULL, NULL, TRUE, NULL, 'The $1,750-per-week tuition deposit is fully refundable until April 1. After that date, no refunds are given for any reason.', 'Food allergies and dietary needs can be fully accommodated if the camp is told in advance. The chef cooks all meals from scratch.', 'Camp is on the shore of Merrymeeting Lake and has a sandy beach. All staff must be certified lifeguards. There is at least 1 counselor for every 3 campers, and no more than 9 campers per week. Boat lessons continue in rain unless there is thunder or lightning. The camp provides all watersports and safety equipment and uses a Supra SV450 boat in 2027.', NULL, NULL, 2027, '94edb9e9-cf6e-532b-b587-06455b1a6149', 'water-monkey-camp-new-durham', ST_GeogFromText('SRID=4326;POINT(-71.1521 43.4637)'), FALSE, TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.watermonkeycamp.com/dates-rates','https://www.watermonkeycamp.com/faq']::text[], '2026-11-13', '2026-11-13', TRUE),
('Lake Winnipesaukee Sailing Association Youth Sailing School', 'Lake Winnipesaukee Sailing Association (LWSA)', 'https://www.lwsa.org/', NULL, 'info@lwsa.org', '1-603-589-1177', '25 Davis Road', 'Gilford', 'NH', '03247', 'New Hampshire', 'specialty', ARRAY['sports']::text[], NULL, ARRAY['Sailing lessons','Optimist and 420 racing classes','Junior instructor training (Advanced Seamanship)']::text[], NULL, 7, 18, NULL, NULL, 'A nonprofit sailing school on Lake Winnipesaukee in Gilford with US Sailing certified instructors. Kids 7 to 18 take one or two week classes, 9am to 4pm on weekdays (half days for 7 year olds), from beginner levels to racing.', NULL, NULL, 190, 615, 410, 'week', NULL, NULL, NULL, TRUE, NULL, NULL, 'Sailors must pass a swim test or assessment and wear a fitted vest-style life jacket; loaner jackets are available.', NULL, NULL, 2026, 'b2048984-c71c-56c0-9f4c-26dfe25e97bc', 'lake-winnipesaukee-sailing-association-youth-sailing-school-gilford', ST_GeogFromText('SRID=4326;POINT(-71.3758 43.5195)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.lwsa.org/','https://www.lwsa.org/level-1-ages-8-10','https://www.lwsa.org/school']::text[], '2026-11-13', '2026-11-13', TRUE),
('Manchester Day Camp (Manchester Summer Program)', 'The Granite YMCA', 'https://www.graniteymca.org/camps/day-camp/manchester/', 'https://ymcagranite.sgasoftware.com/Sales/Product?ProductID=62001-68999&ProductTypeID=610,650&DT=GroupedList&DL=100', 'ttorres@graniteymca.org', '603.232.8656', '30 Mechanic St', 'Manchester', 'NH', '03101', 'New Hampshire', 'day', ARRAY['sports','arts','STEM']::text[], NULL, ARRAY['Swimming','STEM','Creative arts','Sports and games','Field trips','Nutrition and healthy lifestyle instruction','Cooking (specialty camp)','Themed weekly events','Teen travel trips']::text[], NULL, 6, 16, 1, 11, 'YMCA day camp at the Downtown Manchester Y. It has three programs: a state-licensed summer program for children entering grades 1-5, specialty camps for grades 3-6, and Teen Trip, a travel day camp around northern New England for grades 7-11.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, TRUE, 'A $35 deposit per camper per week is nonrefundable. Cancel more than 6 weeks before the camp week for a full refund less the deposit; 3 to 6 weeks before, a $65 admin fee is also charged; less than 3 weeks before, no refund. Payment is due in full at registration.', NULL, NULL, NULL, NULL, 2026, '6fa49857-08fb-59b0-addc-4ea06ae20d61', 'manchester-day-camp-manchester-summer-program-manchester', ST_GeogFromText('SRID=4326;POINT(-71.4548 42.9956)'), TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://www.graniteymca.org/camps/day-camp/manchester/','https://www.graniteymca.org/dev/wp-content/uploads/2024/01/Summer-Billing-Schedule.pdf','https://www.graniteymca.org/locations/manchester/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Westwood Park Day Camps (Sports Camps at Westwood Park)', 'YMCA of Greater Nashua', 'https://nmymca.org/camps/westwood-park-day-camps/', 'https://operations.daxko.com/Online/5286/ProgramsV2/Search.mvc?category_ids=CAT352&location_ids=B249', 'camp@nmymca.org', '603.598.1533', '90 Northwest Boulevard', 'Nashua', 'NH', '03063', 'New Hampshire', 'day', ARRAY['sports']::text[], NULL, ARRAY['Multi-sport','Basketball','Flag football','Soccer','Pickleball','NinjaZone obstacle courses','Volleyball','Sports performance training','Arts and crafts (Girls on the Go!)']::text[], NULL, NULL, NULL, 1, 12, 'The YMCA runs week-long sports day camps for grades 1-12 at Westwood Park, an indoor facility with basketball/volleyball courts and a turf field. There are full-week camps for grades 1-6, half-day camps for older kids, and Dig Deep volleyball clinics.', NULL, NULL, 340, 525, 440, 'week', TRUE, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2026, 'afd3e2cf-fb62-5d36-aa9e-dc45b2f23ce6', 'westwood-park-day-camps-sports-camps-at-westwood-park', ST_GeogFromText('SRID=4326;POINT(-71.4676 42.7654)'), TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://nmymca.org/camps/westwood-park-day-camps/','https://nmymca.org/wp-content/uploads/2026/01/YMCAofGN_SummerCampGuide_2026_Final.1.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('Windsor Mountain International Summer Camp', NULL, 'https://windsormountain.org/', 'https://windsor.campintouch.com/ui/forms/application/camper/App', NULL, '603-478-3166', 'One World Way', 'Windsor', 'NH', '03244', 'New Hampshire', 'sleepaway', ARRAY['arts','performing_arts','sports','nature']::text[], NULL, ARRAY['performing arts','sailing','sports','cooking/culinary arts','outdoor adventure','music','creative/visual arts','film-making','ropes courses','wilderness trips']::text[], NULL, 7, 16, NULL, NULL, 'A non-competitive, co-ed overnight camp for ages 7-16 on a 365-acre lakefront site in Windsor, New Hampshire, with campers from the US and abroad. Campers pick their own activities, and sessions run 2, 3.5, 6 or 7 weeks.', NULL, NULL, 4295, 8195, NULL, 'session', NULL, NULL, NULL, TRUE, NULL, NULL, 'Camp is on a private 365-acre lakefront site with sailing as a specialty area.', TRUE, 'https://find.acacamps.org/camp_profile.php?camp_id=1731', 2027, 'b9a8265f-f8d0-5c05-a46b-0f96bc42826c', 'windsor-mountain-international-summer-camp-windsor', ST_GeogFromText('SRID=4326;POINT(-72.0136 43.113)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://windsormountain.org/new-families/','https://windsormountain.org/new-families/dates-and-rates/']::text[], '2026-11-13', '2026-11-13', TRUE),
('YMCA Camp Mi-Te-Na', 'The Granite YMCA', 'https://campmitena.org/', 'https://campmitena.org/sign-up-for-camp/', 'stownes@graniteymca.org', '603-232-8642', '65 YMCA Rd.', 'Alton', 'NH', '03809', 'New Hampshire', 'sleepaway', NULL, NULL, ARRAY['Campfires','Specialty activities','Socials with Camp Foss','Out-of-camp trips and excursions','Sign-up activity opportunities']::text[], 'boys', 8, 15, NULL, NULL, 'A Granite YMCA overnight camp for boys ages 8 to 15 in Alton, NH, with campfires, specialty activities, trips and socials with sister Camp Foss. Stays run one week, two weeks, one month or the full summer, June 27 to August 21, 2027.', NULL, NULL, 1650, 10450, NULL, 'session', NULL, NULL, NULL, TRUE, 'For a non-medical, non-emergency cancellation, you must contact the Enrollment Coordinator at least four weeks before the session starts. Deposits taken at registration are non-refundable. A medical cancellation needs a doctor''s note saying the camper cannot take part. Final payment is due May 15, 2027.', NULL, NULL, NULL, NULL, 2027, '01a58fea-ad97-5ac3-a0b0-3cdc90d303bd', 'ymca-camp-mi-te-na', ST_GeogFromText('SRID=4326;POINT(-71.2406 43.4883)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://campmitena.org/','https://campmitena.org/contact/','https://campmitena.org/dates-and-rates/','https://campmitena.org/faq/']::text[], '2026-11-13', '2026-11-13', TRUE),
('McAuliffe-Shepard Discovery Center STEM Summer Camps', 'McAuliffe-Shepard Discovery Center', 'https://www.starhop.com/summer-camps', 'https://www.jotform.com/form/253555113088154', 'swiehe@starhop.com', '(603) 271-7827', '2 Institute Drive', 'Concord', 'NH', '03301', 'New Hampshire', 'day', ARRAY['STEM']::text[], NULL, ARRAY['Coding and programming','Engineering design','Astronomy with telescopes','Fossils and paleontology','Model and air rockets','Astronaut training','Ecosystems and weather']::text[], NULL, 5, 14, NULL, NULL, 'Weekly STEM day camps at a science center and planetarium in Concord, NH. Each week has a theme (coding, astronomy, dinosaurs, rockets, astronauts, earth science) aimed at a specific age group.', NULL, NULL, 288, 360, 360, 'week', NULL, NULL, NULL, NULL, 'Full refund if you cancel at least 30 days before the session starts. No refund if you cancel less than 30 days before, except for a documented emergency. Cancellations must be sent by email.', NULL, NULL, NULL, NULL, 2026, '5c3483dd-0ee9-5bd2-bb80-e9846733967c', 'mcauliffe-shepard-discovery-center-stem-summer-camps-concord', ST_GeogFromText('SRID=4326;POINT(-71.5376 43.2081)'), TRUE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.starhop.com/summer-camps']::text[], '2026-11-13', '2026-11-13', TRUE),
('Upper Valley Music Center Summer Camps and Programs', 'Upper Valley Music Center', 'https://uvmusic.org/programs/summer', 'https://uvmusic.org/registration/group-class-ensemble-registration', 'info@uvmusic.org', '603-448-1642', '8 South Park Street', 'Lebanon', 'NH', '03766', 'New Hampshire', 'specialty', ARRAY['performing_arts','arts']::text[], NULL, ARRAY['Singing','Musical theater','Drumming and music and movement','Drawing and painting to music','Violin and viola audition preparation']::text[], NULL, 5, 18, NULL, NULL, 'Upper Valley Music Center, a community music school in Lebanon, NH, runs short half-day summer camps for children and teens: Singing for the Stage (ages 10 to 13), Rhythm Kids music and movement (ages 5 to 10), Painting to the Music with AVA Gallery (ages 6 to 12) and an All-State audition week for high school string players.', NULL, NULL, 208, 325, NULL, 'session', NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2026, '5316ab61-9f9b-5b8d-9b23-604fa151a4f4', 'upper-valley-music-center-summer-camps-and-programs-lebanon', ST_GeogFromText('SRID=4326;POINT(-72.2538 43.6354)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://uvmusic.org/news/class-type/summer-camp','https://uvmusic.org/news/classes/all-state-audition-intensive','https://uvmusic.org/news/classes/rhythm-kids-camp','https://uvmusic.org/news/classes/singing-for-the-stage-summer-2025','https://uvmusic.org/programs/summer','https://uvmusic.org/registration/group-class-ensemble-registration']::text[], '2026-11-13', '2026-11-13', TRUE),
('WildQuest Day Camps', 'Prescott Farm Environmental Education Center', 'https://prescottfarm.org/service/wildquest-day-camps/', 'http://prescottfarm.campbrainregistration.com', 'camp@prescottfarm.org', '(603) 366-5695', '928 White Oaks Road', 'Laconia', 'NH', '03246', 'New Hampshire', 'day', ARRAY['nature']::text[], NULL, ARRAY['nature activities','animal and plant identification','arts and crafts','cooking','Quests','games','hands-on learning']::text[], NULL, 5, 14, NULL, NULL, 'A nature day camp at Prescott Farm in Laconia, NH, running nine themed summer weeks for ages 5 to 14, 9am to 4pm, plus February and April vacation weeks. Campers spend most of the day outdoors with nature activities, animal and plant identification, arts and crafts, cooking, games and hands-on learning.', NULL, NULL, 270, 320, 320, 'week', TRUE, NULL, FALSE, TRUE, 'A $100 non-refundable deposit per session, per child, holds each spot. Cancel more than four weeks before the session for a refund of everything else paid; within four weeks, refunds only if the spot is filled. No refunds for no-shows, missed days or weather.', NULL, NULL, NULL, NULL, 2026, '12d8bfd6-cde1-5dd3-a556-a3029ba21932', 'wildquest-day-camps-laconia', ST_GeogFromText('SRID=4326;POINT(-71.4823 43.5765)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://prescottfarm.org/service/wildquest-day-camps/','https://prescottfarm.org/service/wildquest-day-camps/wildquest-summer-camp/','https://prescottfarm.org/wp-content/uploads/2025/12/2026-Final-Camp-Family-Handbook.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('Wolfeboro Parks & Recreation Summer Day Camp', 'Wolfeboro Parks & Recreation (Town of Wolfeboro)', 'https://www.wolfeboronh.us/300/2026-Day-Camp', 'https://wolfeboro.recdesk.com/Community/Home', 'programmer@wolfeboronh.us', '603-569-5639', 'Foss Field Pavilion, 88 Lehner St.', 'Wolfeboro', 'NH', '03894', 'New Hampshire', 'day', ARRAY['general']::text[], NULL, ARRAY['Swimming','Beach days','Group games','Team building','Sports','Arts and crafts','Weekly field trips','Special events']::text[], NULL, 6, 12, NULL, NULL, 'A town-run summer day camp for ages 6 to 12, Monday to Friday from 9am to 3:30pm at the Foss Field Pavilion. Campers are split into two age groups (6 to 8 and 9 to 12), with beach days on Wednesdays and a weekly field trip.', NULL, NULL, 95, 143, 95, 'week', NULL, NULL, FALSE, TRUE, NULL, NULL, 'Beach days are Wednesdays at Carry Beach (201 Forest Rd.); campers bring a swimsuit and towel.', NULL, NULL, 2026, '56a87aa5-7050-54da-ab37-b87d6c57c235', 'wolfeboro-parks-and-recreation-summer-day-camp-wolfeboro', ST_GeogFromText('SRID=4326;POINT(-71.1692 43.6144)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.wolfeboronh.us/300/2026-Day-Camp','https://www.wolfeboronh.us/DocumentCenter/View/1468/Day-Camp-2026-Parent-Handbook']::text[], '2026-11-13', '2026-11-13', TRUE),
('YMCA Camp Sargent', 'YMCA of Greater Nashua', 'https://nmymca.org/camps/camp-sargent/', 'https://operations.daxko.com/Online/5286/ProgramsV2/Search.mvc?category_ids=CAT352&location_ids=B247', 'camp@nmymca.org', '603-598-1533', '141 Camp Sargent Road', 'Merrimack', 'NH', '03054', 'New Hampshire', 'day', ARRAY['nature','sports','arts','performing_arts','STEM']::text[], NULL, ARRAY['Swimming','Boating','Kayaking','Canoeing','Paddleboarding','Archery','Nature','Arts and crafts','Drama','Ga-ga ball','Farm camp','STEM','Theater production','Leadership training']::text[], NULL, 5, NULL, 0, 12, 'A traditional YMCA day camp on Lake Naticook in Merrimack, NH. It offers a general Summer Fun day camp for grades K-8, weekly morning specialty camps for grades K-9, and a Leaders in Training program for grades 9-12.', NULL, NULL, 270, 880, 410, 'week', TRUE, NULL, NULL, TRUE, NULL, NULL, 'The camp is on Lake Naticook. Swimming and boating are part of the daily program, and a Boating Camp for grades 5-9 teaches kayaking, canoeing, paddleboarding, water safety and life jacket use.', TRUE, 'https://nmymca.org/camps/camp-sargent/', 2026, '1852be95-85a7-54fc-a725-360f78c591c6', 'ymca-camp-sargent-merrimack', ST_GeogFromText('SRID=4326;POINT(-71.5199 42.852)'), TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://nmymca.org/camps/camp-sargent/','https://nmymca.org/wp-content/uploads/2026/01/YMCAofGN_SummerCampGuide_2026_Final.1.pdf','https://tools.usps.com/zip-code-lookup.htm?citybyzipcode']::text[], '2026-11-13', '2026-11-13', TRUE)
